# Cortex interactive shell helpers.
# Installed as /etc/profile.d/02-cortex-shell.sh and regenerated by the app on
# every start; put personal customisations in ~/.bashrc / ~/.profile instead.
#
# Why this exists: installers such as nvm, bun, rustup or opencode append their
# PATH / init lines to ~/.bashrc, but a running shell never re-reads it, so the
# tool "does not exist" until the terminal is restarted. This file re-sources
# ~/.bashrc (and ~/.profile / ~/.bash_profile) as soon as one of them changes
# on disk, so a freshly installed tool works at the very next prompt.
# Opt out with:  export CORTEX_AUTO_RELOAD=0

# Interactive bash only.
[ -n "${BASH_VERSION-}" ] || return 0 2>/dev/null || exit 0
case $- in *i*) ;; *) return 0 2>/dev/null || exit 0 ;; esac

# nvm refuses to load when PREFIX is set (a Termux leftover).
unset PREFIX

# Re-read the user's startup files in the current shell (same as Ubuntu's
# "source ~/.bashrc", plus the login files).
reload() {
    set --
    if [ -f "$HOME/.bashrc" ]; then . "$HOME/.bashrc"; fi
    if [ -f "$HOME/.profile" ]; then . "$HOME/.profile"; fi
    if [ -f "$HOME/.bash_profile" ]; then . "$HOME/.bash_profile"; fi
    __cortex_rc_touch
    echo "Configuration reloaded successfully."
}

# Reference file whose mtime is "the last time this shell read the startup
# files". Comparing with the builtin -nt test costs no fork per prompt.
__cortex_rc_stamp="${TMPDIR:-/tmp}/.cortex-rcwatch.$$"

__cortex_rc_touch() {
    : > "$__cortex_rc_stamp" 2>/dev/null
}

# Sets __cortex_rc_hit to the startup files that changed since the last check.
__cortex_rc_check() {
    __cortex_rc_hit=()
    [ "${CORTEX_AUTO_RELOAD-1}" = "0" ] && return 0
    if [ ! -e "$__cortex_rc_stamp" ]; then
        # Stamp was cleaned up behind our back: start over instead of reloading.
        __cortex_rc_touch
        return 0
    fi
    local f
    for f in "$HOME/.bashrc" "$HOME/.bash_profile" "$HOME/.profile"; do
        if [ -f "$f" ] && [ "$f" -nt "$__cortex_rc_stamp" ]; then
            __cortex_rc_hit+=("$f")
        fi
    done
    if [ "${#__cortex_rc_hit[@]}" -gt 0 ]; then
        __cortex_rc_touch
        printf '\033[2m[cortex] %s changed, reloading\033[0m\n' "${__cortex_rc_hit[*]//$HOME/\~}" >&2
    fi
    return 0
}

__cortex_rc_touch

# Shell-integration marks (OSC 133). The terminal times commands with them and, if enabled in
# Settings, notifies when a long command finishes while Cortex is in the background:
#   C = a command is about to run (PS0), D;<status> = it finished (first thing at the next prompt).
# Opt out with:  export CORTEX_COMMAND_MARKS=0
__cortex_ec=0
__cortex_precmd() {
    __cortex_ec=$?
    if [ "${CORTEX_COMMAND_MARKS-1}" != "0" ]; then
        printf '\033]133;D;%s\007' "$__cortex_ec"
    fi
    return 0
}
# Hands the status of the user's last command on to whatever PROMPT_COMMAND entries follow
# (starship, direnv, a custom prompt ...).
__cortex_restore_status() {
    return "$__cortex_ec"
}
if [ "${CORTEX_COMMAND_MARKS-1}" != "0" ]; then
    case "${PS0-}" in
        *133\;C*) ;;
        *) PS0=$'\033]133;C\007'"${PS0-}" ;;
    esac
fi

# The sourcing has to happen at top level (PROMPT_COMMAND is eval'ed there),
# not inside a function, otherwise `declare` in the user's files would become
# function-local and be lost.
__cortex_rc_cmd='__cortex_rc_check; for __cortex_rc_f in "${__cortex_rc_hit[@]}"; do . "$__cortex_rc_f"; done; unset __cortex_rc_f'

# Our hooks go first so that $? is still the status of the user's command when they run, and the
# status is restored before anyone else's hook sees it.
case "$(declare -p PROMPT_COMMAND 2>/dev/null)" in
    "declare -a"*)
        case " ${PROMPT_COMMAND[*]} " in
            *__cortex_precmd*) ;;
            *) PROMPT_COMMAND=("__cortex_precmd" "$__cortex_rc_cmd" "__cortex_restore_status" "${PROMPT_COMMAND[@]}") ;;
        esac
        ;;
    *)
        case ";${PROMPT_COMMAND-};" in
            *__cortex_precmd*) ;;
            *) PROMPT_COMMAND="__cortex_precmd; $__cortex_rc_cmd; __cortex_restore_status${PROMPT_COMMAND:+;$PROMPT_COMMAND}" ;;
        esac
        ;;
esac
unset __cortex_rc_cmd
